+
+void Positioner::setBlockingAreas(const QVariantList &areas,
+                                  const QSizeF &cellSize,
+                                  const QRectF &itemArea,
+                                  Qt::Orientation flow,
+                                  Qt::LayoutDirection direction)
+{
+    m_cellSize = cellSize;
+    m_flow = flow;
+
+    // Work in stripe coordinates: x along a stripe, y across stripes
+    const bool rows = (flow == Qt::Horizontal);
+    const auto toStripes = [rows](const QRectF &rect) {
+        return rows ? rect : QRectF(rect.y(), rect.x(), rect.height(), rect.width());
+    };
+    const QSizeF cell = rows ? cellSize : cellSize.transposed();
+    const QRectF item = toStripes(itemArea);
+
+    QList<int> cells;
+
+    if (m_perStripe > 0 && !cellSize.isEmpty()) {
+        for (const QVariant &value : areas) {
+            QRectF area = value.toRectF();
+
+            // Cells are laid out from the right: rows from the last column, columns from x = 0 leftwards
+            if (direction == Qt::RightToLeft) {
+                area.moveLeft((rows ? m_perStripe * cellSize.width() : 0) - area.right());
+            }
+
+            area = toStripes(area);
+
+            const int lastPos = std::min(m_perStripe - 1, int(std::floor(area.right() / cell.width())));
+            const int lastStripe = int(std::floor(area.bottom() / cell.height()));
+
+            for (int stripe = std::max(0, int(std::floor(area.top() / cell.height())) - 1); stripe <= lastStripe; ++stripe) {
+                for (int pos = std::max(0, int(std::floor(area.left() / cell.width())) - 1); pos <= lastPos; ++pos) {
+                    if (item.translated(pos * cell.width(), stripe * cell.height()).intersects(area)) {
+                        cells.append((stripe * m_perStripe) + pos);
+                    }
+                }
+            }
+        }
+    }
+
+    std::sort(cells.begin(), cells.end());
+    cells.erase(std::unique(cells.begin(), cells.end()), cells.end());
+
+    if (m_blockedCells == cells) {
+        return;
+    }
+
+    // In manual mode items keep their positions, in sorted mode they flow around the new cells
+    const bool reset = !m_enabled && m_folderModel;
+
+    if (reset) {
+        beginResetModel();
+    }
+
+    m_blockedCells = cells;
+
+    if (reset) {
+        endResetModel();
+    }
+
+    Q_EMIT blockedCellsChanged();
+}
+
+bool Positioner::isBlocked(int row) const
